## TDD Red-Green-Refactor: Error Handling and Retries

Implement robust error handling and retry mechanisms for RPC calls.

### Red Phase - Write Failing Tests First

```typescript
// packages/rpc/tests/errors.test.ts
import { describe, it, expect } from 'vitest'
import { createRPCClient, RPCError, RetryPolicy } from '../src'

describe('Error Handling', () => {
  it('should wrap remote errors in RPCError', async () => {
    const client = createRPCClient('https://api.dotdo.dev')

    await expect(client.throwError()).rejects.toThrow(RPCError)

    try {
      await client.throwError()
    } catch (e) {
      expect(e).toBeInstanceOf(RPCError)
      expect(e.code).toBe('REMOTE_ERROR')
      expect(e.remoteStack).toBeDefined()
    }
  })

  it('should distinguish error types', async () => {
    const client = createRPCClient('https://api.dotdo.dev')

    // Network error
    await expect(client.networkFail()).rejects.toMatchObject({
      code: 'NETWORK_ERROR',
      retryable: true,
    })

    // Validation error
    await expect(client.validate(null)).rejects.toMatchObject({
      code: 'VALIDATION_ERROR',
      retryable: false,
    })

    // Timeout
    await expect(client.slow({ timeout: 100 })).rejects.toMatchObject({
      code: 'TIMEOUT',
      retryable: true,
    })
  })
})

describe('Retry Mechanism', () => {
  it('should retry on transient failures', async () => {
    const client = createRPCClient('https://api.dotdo.dev', {
      retry: { maxAttempts: 3, backoff: 'exponential' },
    })
    let attempts = 0
    client.onAttempt(() => attempts++)

    // Server fails twice, succeeds third time
    const result = await client.flakyOperation()

    expect(attempts).toBe(3)
    expect(result).toBe('success')
  })

  it('should respect retry policy', async () => {
    const policy: RetryPolicy = {
      maxAttempts: 5,
      backoff: 'exponential',
      baseDelay: 100,
      maxDelay: 5000,
      retryOn: (error) => error.code === 'RATE_LIMITED',
    }

    const client = createRPCClient('https://api.dotdo.dev', { retry: policy })
    const result = await client.rateLimitedEndpoint()

    expect(result).toBeDefined()
  })

  it('should support per-call retry override', async () => {
    const client = createRPCClient('https://api.dotdo.dev')

    // Override default retry for this call
    const result = await client.critical({
      retry: { maxAttempts: 10 },
    })

    expect(result).toBeDefined()
  })

  it('should emit retry events for observability', async () => {
    const client = createRPCClient('https://api.dotdo.dev')
    const retryEvents: any[] = []

    client.on('retry', (event) => retryEvents.push(event))

    await client.flakyOperation()

    expect(retryEvents.length).toBeGreaterThan(0)
    expect(retryEvents[0]).toMatchObject({
      attempt: expect.any(Number),
      delay: expect.any(Number),
      error: expect.any(Object),
    })
  })
})

describe('Circuit Breaker', () => {
  it('should open circuit after threshold failures', async () => {
    const client = createRPCClient('https://api.dotdo.dev', {
      circuitBreaker: {
        threshold: 5,
        resetTimeout: 1000,
      },
    })

    // Fail 5 times
    for (let i = 0; i < 5; i++) {
      await client.alwaysFails().catch(() => {})
    }

    // Circuit should be open now
    await expect(client.anyMethod()).rejects.toMatchObject({
      code: 'CIRCUIT_OPEN',
    })
  })
})
```

### Green Phase - Minimal Implementation

- RPCError class with error codes
- RetryPolicy configuration
- Exponential backoff implementation
- Circuit breaker pattern

### Refactor Phase

- Jitter for backoff (avoid thundering herd)
- Retry budget (limit retries per time window)
- Error aggregation for batch failures
- Dead letter queue for exhausted retries

