## TDD: Cost/Token Tracking

Implement comprehensive cost and token tracking across all AI operations.

### Red Phase - Write Failing Tests First
```typescript
// tests/ai/tracking.test.ts
import { ai, Tracker, getCosts } from '@dotdo/ai'

test('tracks tokens per request', async () => {
  const result = await ai`Hello world`
  expect(result.$meta.tokens.input).toBeGreaterThan(0)
  expect(result.$meta.tokens.output).toBeGreaterThan(0)
  expect(result.$meta.tokens.total).toBe(
    result.$meta.tokens.input + result.$meta.tokens.output
  )
})

test('calculates cost per request', async () => {
  const result = await ai`Hello`.with({ model: 'claude-3-opus' })
  expect(result.$meta.cost).toBeGreaterThan(0)
  expect(result.$meta.cost).toBeLessThan(1) // Sanity check
})

test('Tracker aggregates across requests', async () => {
  const tracker = new Tracker()
  await tracker.track(ai`Request 1`)
  await tracker.track(ai`Request 2`)

  const stats = tracker.getStats()
  expect(stats.totalRequests).toBe(2)
  expect(stats.totalTokens).toBeGreaterThan(0)
  expect(stats.totalCost).toBeGreaterThan(0)
})

test('getCosts returns pricing table', () => {
  const costs = getCosts('claude-3-opus')
  expect(costs.inputPer1kTokens).toBeDefined()
