test('tracking persists to DO storage', async () => {
  const tracker = new Tracker({ persist: true })
  await tracker.track(ai`Tracked request`)

  // Simulate DO restart
  const newTracker = new Tracker({ persist: true })
  const history = await newTracker.getHistory()
  expect(history.length).toBeGreaterThan(0)
})
